import math
from functools import reduce

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(math.gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1
    # LCM(a, b) = |a*b| / GCD(a, b)
    return reduce(lambda a, b: abs(a*b) // math.gcd(a, b), numbers)

def count_good_partitions(sequence):
    n = len(sequence)
    count = 0
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        lcm_A = list_lcm(A_k)
        gcd_B = list_gcd(B_k)

        if lcm_A == gcd_B:
            count += 1
    return count

# Testing n=5 and n=6 with consecutive integers
seq_5 = list(range(1, 6))
seq_6 = list(range(1, 7))

print(f"n=5 (1, 2, 3, 4, 5): {count_good_partitions(seq_5)}")
print(f"n=6 (1, 2, 3, 4, 5, 6): {count_good_partitions(seq_6)}")
